#!/usr/bin/env bash
# Build the H109 slow example library in groups, on one core (LEAN_NUM_THREADS=1), each
# group under ONE total budget (default and at most 600 s; decision H436: partition the
# library into separately bounded 600 s groups). Inside a group the modules build one at a
# time in import order, each under the time its group has left, so the module that spends
# the group's budget is named. Modules come from SoliditySlowExamples.lean (generated by
# register.sh); SLOW_GROUPS below names the groups but the last; every other slow module is in
# `rest`, so a new slow module is always in some group. Run after
# `lake build Solidity SolidityExamples`: a group's budget then covers its own modules.
#
# Usage: scripts/ci/build-slow-examples.sh [--list | --group NAME]
#   --list        print "<group>\t<module>" in build order and exit
#   --group NAME  build that group only (default: every group, in SLOW_GROUPS order, then rest)
# Environment: SLOW_EXAMPLE_BUDGET_S, the per-group budget (default 600; only 1..600).
# Prints "PASS|FAIL|TIMEOUT|SKIP <module> <seconds>s" per module and
# "GROUP <name> PASS|FAIL <seconds>s of <budget>s" per group; SKIP is a module whose slow
# import failed, or that the group's spent budget left no time for. Exit 0 every group
# passed, 1 a build failed or a group ran out of time, 2 usage error.
set -uo pipefail
root=$(git rev-parse --show-toplevel) || exit 2
cd "$root" || exit 2
export PATH="$HOME/.elan/bin:$PATH"

# group<TAB>space-separated modules; measured one core, 4-core VM, 2026-11-09/10:
# OpenLoops 14 s + RowsNine 553 s; rest: DecisionGaps 242, RevertData 165,
# DecisionResidue 88, eleven others under 2 s each (about 510 s).
SLOW_GROUPS='rowsnine	Solidity.Examples.Tactics.OpenLoops Solidity.Examples.Tactics.OpenLoops.RowsNine'

budget=${SLOW_EXAMPLE_BUDGET_S:-600}
# 1..600 only: `timeout 0` would disable the deadline, and above 600 needs an ESCALATE (H134).
case "$budget" in ''|*[!0-9]*) echo "build-slow-examples: bad budget" >&2; exit 2;; esac
budget=$((10#$budget))
[ "$budget" -ge 1 ] || { echo "build-slow-examples: budget must be at least 1 s (0 disables timeout)" >&2; exit 2; }
[ "$budget" -le 600 ] || { echo "build-slow-examples: budget $budget s exceeds 600 s (H134); ESCALATE instead" >&2; exit 2; }
list=0 only=""
usage() { echo "usage: build-slow-examples.sh [--list | --group NAME]" >&2; exit 2; }
case "${1:-}" in
  --list) list=1; [ $# -eq 1 ] || usage;;
  --group) [ $# -eq 2 ] && [ -n "$2" ] || usage; only=$2;;
  "") ;;
  *) usage;;
esac
# "<group>\t<module>\t<slow imports, comma-separated>" in build order, groups in order.
plan=$(SLOW_GROUPS="$SLOW_GROUPS" python3 - <<'PY'
import os, pathlib, re, sys
imp = re.compile(r"^\s*(?:(?:public|private|meta)\s+)*import(?:\s+all)?\s+(.+)$")
def imports(path):
    out = []
    for line in path.read_text().splitlines():
        m = imp.match(line)
        if m: out += m.group(1).split("--", 1)[0].split()
    return out
slow = imports(pathlib.Path("SoliditySlowExamples.lean"))
if not slow: sys.exit("build-slow-examples: no modules in SoliditySlowExamples.lean")
deps = {m: [d for d in imports(pathlib.Path(m.replace(".", "/") + ".lean")) if d in slow] for m in slow}
order, state = [], {}
def visit(m):
    if state.get(m) == 2: return
    if state.get(m) == 1: sys.exit("build-slow-examples: import cycle at " + m)
    state[m] = 1
    for d in sorted(deps[m]): visit(d)
    state[m] = 2; order.append(m)
for m in sorted(slow): visit(m)
groups, member = [], {}
for line in os.environ["SLOW_GROUPS"].strip().splitlines():
    name, mods = line.split("\t", 1)
    if name == "rest" or name in groups: sys.exit("build-slow-examples: bad group name " + name)
    groups.append(name)
    for m in mods.split():
        if m not in deps: sys.exit("build-slow-examples: group %s names %s, not a slow module" % (name, m))
        if m in member: sys.exit("build-slow-examples: %s is in two groups" % m)
        member[m] = name
groups.append("rest")
for g in groups:
    for m in order:
        if member.get(m, "rest") == g:
            print("%s\t%s\t%s" % (g, m, ",".join(deps[m])))
PY
) || exit 2
if [ "$list" = 1 ]; then cut -f1,2 <<<"$plan"; exit 0; fi
if [ -n "$only" ] && ! cut -f1 <<<"$plan" | grep -qx -- "$only"; then
  echo "build-slow-examples: no group $only (groups: $(cut -f1 <<<"$plan" | uniq | tr '\n' ' '))" >&2; exit 2
fi
failed=0; bad=","; group=""; gstart=0; gfail=0
end_group() {
  [ -n "$group" ] || return 0
  local spent=$(( $(date +%s) - gstart ))
  if [ "$gfail" -eq 0 ]; then echo "GROUP $group PASS ${spent}s of ${budget}s"
  else failed=1; echo "GROUP $group FAIL ${spent}s of ${budget}s"; fi
}
while IFS=$'\t' read -r g m deps; do
  [ -n "$m" ] || continue
  [ -z "$only" ] || [ "$g" = "$only" ] || continue
  if [ "$g" != "$group" ]; then end_group; group=$g; gstart=$(date +%s); gfail=0; fi
  # A module whose slow import failed would rebuild it under its own time and fail too.
  skip=""; IFS=, read -ra ds <<<"$deps"
  for d in "${ds[@]}"; do case "$bad" in *",$d,"*) skip="imports failed $d";; esac; done
  left=$(( budget - ($(date +%s) - gstart) ))
  [ -n "$skip" ] || [ "$left" -ge 1 ] || skip="group $group has no time left"
  if [ -n "$skip" ]; then gfail=1; bad="$bad$m,"; echo "SKIP $m ($skip)"; continue; fi
  start=$(date +%s)
  LEAN_NUM_THREADS=1 timeout --kill-after=10s "${left}s" lake build "$m" </dev/null; st=$?
  secs=$(( $(date +%s) - start ))
  if [ "$st" -eq 0 ]; then echo "PASS $m ${secs}s"
  else
    gfail=1; bad="$bad$m,"
    if [ "$st" -eq 124 ] || [ "$st" -eq 137 ]; then echo "TIMEOUT $m ${secs}s (group $group: ${budget}s total)"
    else echo "FAIL $m ${secs}s (exit $st)"; fi
  fi
done <<<"$plan"
end_group
exit "$failed"
